export {pathDetail,careerDetail,earningsPanel,educationCostsPanel} from './context-ui.js?v=0.31.0';
import {majors,subjectLink,entitiesForPlan} from './catalog-data.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {directions} from './content.js?v=0.31.0';
import {careers,pathCareers,collegeExamples,FINANCE_RELEASE,financeSources} from './finance-data.js?v=0.31.0';
import {calculateCollege,businessScenario,linkedPlans,requirementContext,coverageMatrix} from './finance.js?v=0.31.0';

export const usd=n=>n===null||n===undefined?'Not available':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n);
const ext=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${h(label)} ↗</a>`;
const more=body=>`<details class="more-info"><summary>More info</summary><div>${body}</div></details>`;
const status=s=>`<span class="fact-status">${h(({editorial:'Editorial connections',sourced:'Source checked',estimate:'Estimate / scenario',not_available:'Not available',not_applicable:'Varies by career',needs_verification:'Needs review'})[s]||s)}</span>`;
const pageHead=(eyebrow,title,copy)=>`<div class="page-intro context-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${h(title)}</h1><p class="intro-copy">${h(copy)}</p></div><a class="button secondary" href="#/directions">Browse directions ↗</a></div>`;
const selectOptions=(choices,value)=>choices.map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${h(label)}</option>`).join('');
const evidenceTypes=[['user_scenario','My scenario'],['published_budget','Published college budget'],['college_calculator','College net-price calculator'],['college_offer','College aid offer']];
const periods=[['academic_year','One academic year'],['term','One term'],['whole_program','Whole program']];
function planInput(p,i,key,label,type='text',help=''){return `<div class="field"><label class="label" for="fp-${i}-${key}">${label}</label><input id="fp-${i}-${key}" data-finance-plan="${i}" data-finance-field="${key}" type="${type}" ${type==='number'?'min="0" max="100000000" step="0.01"':'maxlength="500"'} value="${h(p[key])}" placeholder="${type==='number'?'Unknown':''}">${help?more(`<p>${help}</p>`):''}</div>`;}
function planSelect(p,i,key,label,options){return `<div class="field"><label class="label" for="fp-${i}-${key}">${label}</label><select id="fp-${i}-${key}" data-finance-plan="${i}" data-finance-field="${key}">${selectOptions(options,p[key])}</select></div>`;}
function planArea(p,i,key,label){return `<div class="field"><label class="label" for="fp-${i}-${key}">${label}</label><textarea id="fp-${i}-${key}" data-finance-plan="${i}" data-finance-field="${key}" maxlength="2000">${h(p[key])}</textarea></div>`;}
export function pathFinancePreview(id){const cs=(pathCareers[id]||[]).map(cid=>careers.find(c=>c.id===cid));return `<div class="finance-preview"><span class="overline">EDUCATION & FINANCIAL CONTEXT</span><p>Texas requirements · Austin pay · College costs & aid</p><a class="text-link" href="#/path/${id}">Explore education & money ↗</a></div>`;}
export function unmappedFinance(){return `<section class="finance-unmapped"><h4>Explore the career connections.</h4><p>A custom subject has no single salary.</p><a class="text-link" href="#/catalog">Browse careers with Austin pay →</a><a class="text-link" href="#/money">Build an education budget →</a></section>`;}
function sourceLine(url,label='Source and scope'){return `<p class="source-line">${ext(label,url)} · Checked ${FINANCE_RELEASE}</p>`;}
function schoolBenchmarks(){return `<details class="disclosure college-benchmarks"><summary>Austin college prices · 2026–2027 · before aid</summary><p>These illustrate different cost structures. They are not a recommended college list or a quote for a particular major. All amounts cover one academic year; no aid is assumed.</p><div class="benchmark-grid">${collegeExamples.map(e=>`<article><span class="overline">PUBLISHED BUDGET</span><h3>${e.institution}</h3><p>${e.residency} · ${e.enrollment}<br>${e.year} · ${e.living}</p><dl class="budget-rows"><div><dt>Tuition & fees</dt><dd>${usd(e.tuitionMin)}${e.tuitionMax!==e.tuitionMin?`–${usd(e.tuitionMax)}`:''}</dd></div><div><dt>Total annual cost</dt><dd>${usd(e.totalMin)}${e.totalMax!==e.totalMin?`–${usd(e.totalMax)}`:''}</dd></div></dl><p>${e.note}</p>${sourceLine(e.sourceURL,'Published costs')}<p>${ext('College calculator / aid information',e.calculatorURL)}</p></article>`).join('')}</div></details>`;}
function linkedPlanSummary(state,entityId){const ps=linkedPlans(state.finance,entityId);return ps.length?`<div class="linked-costs">${ps.map(p=>{const c=calculateCollege(p);return `<article><h4>${h(p.institution||'Unnamed college')}</h4><p>${h(p.program||'Program not entered')} · ${h(p.year||'Year not entered')} · ${h(periods.find(([id])=>id===p.period)?.[1])}</p><p>${h(evidenceTypes.find(([id])=>id===p.evidenceType)?.[1])} · Net price: <strong>${usd(c.netPrice)}</strong></p><a href="#/money" class="text-link">Review this saved estimate ↗</a></article>`;}).join('')}</div>`:'<p class="missing-fact">No saved education budget yet. Choose an actual college or training provider and program; this is not a zero cost.</p>';}
export function moneyPage(state,business=false){if(business)return businessPage(state);const f=state.finance;return `${pageHead('EDUCATION & MONEY','Make a college plan you can understand.','College costs. Real aid. A plan that adds up.')}<section class="finance-intro"><div><span class="overline">COST → GRANTS → NET PRICE → FUNDING</span><h2>Give each number its proper place.</h2><p>Use one academic year, term, or whole program per plan. Leave unknown amounts blank.</p></div><a class="button" href="#/money" data-action="college-add">+ Add a college plan</a></section>${schoolBenchmarks()}<div class="money-workspace">${f.plans.map((p,i)=>collegeEditor(p,i,f)).join('')||'<div class="empty-state"><h3>Start with a college you’re curious about.</h3><p>Add an annual budget or a saved calculator estimate. You do not need to enter family income, tax documents, FAFSA credentials, or identifying numbers.</p><button class="button" data-action="college-add">Add my first college plan →</button></div>'}</div>${f.plans.length?`<div class="finance-compare-wrap"><h2>Compare the same concepts.</h2><p>Choose up to three plans above. Different years, periods, or assumptions remain labeled.</p><div id="college-comparison">${collegeComparison(f)}</div></div>`:''}<section class="context-panel aid-guidance"><h2>Keep aid conditions visible.</h2><p>Grants and scholarships reduce the price. Loans are borrowing. Work-study is an opportunity to earn, not an automatic credit on the bill. Pending applications do not count as awarded aid.</p>${more('<p>Offers have renewal, enrollment, and expiry conditions. An annual budget is not a whole-degree price. A transfer budget includes both schools and transferred credits.</p>')}<div class="button-group"><a class="button secondary" href="${financeSources.aid}" target="_blank" rel="noopener noreferrer">Federal Student Aid guide ↗</a><a class="button secondary" href="${financeSources.compare}" target="_blank" rel="noopener noreferrer">CFPB college planning ↗</a></div></section><section class="finance-data-controls no-print"><label class="check-line"><input type="checkbox" data-finance-setting="includeInReport" ${f.includeInReport?'checked':''}><span>Include my personal college or training plans and business assumptions in my report and its export.</span></label><small>Off by default. Full-draft backups always include these entries. Public career facts and published college examples remain available without personal data.</small><button class="button secondary" data-action="finance-export">Export education & financial context</button><a class="text-link" href="#/money/business">Explore a business scenario ↗</a></section><details class="disclosure"><summary>Sources, coverage & missing information</summary><p>Reviewed snapshot: ${FINANCE_RELEASE}. Austin metro wages refer to May 2025; college examples refer to 2026–2027. These periods are different and are not automatically inflation-adjusted or used to compute a personal return on investment.</p><p>Every catalog pathway and career has education, requirements, cost, and earnings coverage, including explicit unknown states. Texas requirements are summarized for all 62 careers. This release has no verified experience-year earnings series or live college database.</p><p>${coverageMatrix().length} catalog entities covered: ${directions.length} pathways and ${careers.length} careers. ${ext('BLS definitions', 'https://www.bls.gov/oes/oes_ques.htm')}</p></details>`;}
function collegeEditor(p,i,f){return `<details class="college-editor" ${i===f.plans.length-1?'open':''}><summary><span class="college-index">${String(i+1).padStart(2,'0')}</span><span>${h(p.institution||'New college plan')}<small>${h(p.year||'Add year & assumptions')}</small></span><span class="college-summary-net" data-plan-mini="${i}">${usd(calculateCollege(p).netPrice)} net price</span></summary><div class="college-editor-body"><div class="college-meta-grid">${planInput(p,i,'institution','College / campus')}${planInput(p,i,'program','Program / degree')}${planInput(p,i,'year','Academic / award year')}${planInput(p,i,'residency','Residency / district status')}${planInput(p,i,'enrollment','Enrollment / credits')}${planInput(p,i,'living','Living arrangement')}${planSelect(p,i,'period','Period covered',periods)}${planSelect(p,i,'evidenceType','Evidence type',evidenceTypes)}${planInput(p,i,'source','Source reference','text','For example: college calculator saved October 16; no private URL needed.')}${planInput(p,i,'checkedOn','Date checked','date')}</div><fieldset class="college-associations"><legend class="label">Link this plan to directions or careers · optional</legend><div>${entitiesForPlan().map(g=>`<details class="plan-links-group"><summary>${g.label}</summary><div>${g.records.map(d=>`<label><input type="checkbox" data-plan-link="${i}" value="${d.id}" ${p.entityLinks.includes(d.id)?'checked':''}>${h(d.title)}</label>`).join('')}</div></details>`).join('')}</div></fieldset><div class="cost-build"><section><span class="overline">1 / COST OF ATTENDANCE</span>${planSelect(p,i,'costMode','How are costs supplied?',[['itemized','Add cost categories'],['total','Use the source’s total cost']])}<div class="cost-inputs" ${p.costMode==='total'?'hidden':''}>${planInput(p,i,'tuition','Tuition & required fees','number')}${planInput(p,i,'housing','Housing & food','number')}${planInput(p,i,'books','Books, tools & supplies','number')}${planInput(p,i,'transportation','Transportation','number')}${planInput(p,i,'other','Exams & other educational costs','number')}</div><div ${p.costMode==='itemized'?'hidden':''}>${planInput(p,i,'total','Source’s total cost of attendance','number','Total should already include tuition and all covered costs. Do not add it to the itemized fields.')}</div></section><section><span class="overline">2 / GRANTS & SCHOLARSHIPS</span>${planInput(p,i,'grants','Grants & scholarships applied to this period','number','Use 0 if none; leave blank if unknown. A calculator amount remains an estimate.')}${planInput(p,i,'pendingAid','Pending / uncertain aid · record only','number','Not subtracted from price or counted as available funding.')}${planArea(p,i,'renewal','Renewal / expiry / enrollment conditions')}</section><section><span class="overline">3 / HOW YOU MIGHT FUND NET PRICE</span>${planInput(p,i,'cash','Planned family / student cash','number')}${planInput(p,i,'studentLoan','Student loan net proceeds','number')}${planInput(p,i,'parentLoan','Parent loan net proceeds','number')}${planInput(p,i,'privateLoan','Private loan net proceeds','number')}${planInput(p,i,'work','Planned earned work income','number','Count realistic earnings, not just an offered work-study allocation.')}</section></div>${planArea(p,i,'assumptions','Assumptions / changes to review')}<label class="check-line"><input type="checkbox" data-finance-plan="${i}" data-finance-field="reviewed" ${p.reviewed?'checked':''}><span>I checked the source, period, and assumptions. These remain an estimate or offer under its stated conditions.</span></label><div class="college-calculation" id="college-calculation-${i}" aria-live="polite">${collegeCalculation(p)}</div><div class="college-editor-actions"><label class="check-line"><input type="checkbox" data-college-compare="${p.id}" ${f.compare.includes(p.id)?'checked':''}><span>Compare this plan</span></label><button class="text-link" data-action="college-remove" data-index="${i}">Remove this plan</button></div></div></details>`;}
export function collegeCalculation(p){const c=calculateCollege(p);const vals=[['Cost of attendance',c.total],['Less grants & scholarships',c.total!==null&&c.netPrice!==null?c.total-c.netPrice:null],['Net price',c.netPrice],['Planned funding',c.funding],['Unresolved funding / excess',c.gap]];return `<div class="calculation-label">${h(evidenceTypes.find(([id])=>id===p.evidenceType)?.[1])} · ${h(periods.find(([id])=>id===p.period)?.[1])}</div><dl class="cost-equation">${vals.map(([k,v],i)=>`<div ${i===2?'class="net-price"':''}><dt>${k}</dt><dd>${usd(v)}</dd></div>`).join('')}</dl><p>Borrowing net proceeds: ${usd(c.borrowing)}. Borrowing is not a discount; principal owed and interest can differ from net proceeds.</p>${c.missing.length?'<p class="missing-inputs">Some amounts are unknown. Add the missing cost, grant, or funding inputs to complete their respective calculations.</p>':''}${c.invalid.length?`<p class="calculation-warning">Check invalid amounts: ${c.invalid.map(h).join(', ')}. Use nonnegative numeric values.</p>`:''}${c.warnings.map(x=>`<p class="calculation-warning">${h(x)}</p>`).join('')}`;}
export function collegeComparison(f){const ps=f.compare.map(id=>f.plans.find(p=>p.id===id)).filter(Boolean);if(!ps.length)return '<p class="data-note">Select “Compare this plan” on up to three saved plans.</p>';const mismatched=new Set(ps.map(p=>`${p.period}:${p.year}`)).size>1;const rows=[['Program',p=>p.program||'Not entered'],['Period / year',p=>`${periods.find(([id])=>id===p.period)?.[1]} · ${p.year||'Unknown year'}`],['Residency / living',p=>`${p.residency||'Unknown'} · ${p.living||'Unknown'}`],['Evidence',p=>evidenceTypes.find(([id])=>id===p.evidenceType)?.[1]],['Cost of attendance',p=>usd(calculateCollege(p).total)],['Net price after grants',p=>usd(calculateCollege(p).netPrice)],['Borrowing net proceeds',p=>usd(calculateCollege(p).borrowing)],['Unresolved funding / excess',p=>usd(calculateCollege(p).gap)],['Renewal & conditions',p=>p.renewal||'Not recorded'],['Source / checked',p=>`${p.source||'Missing source'} · ${p.checkedOn||'Missing date'}`]];return `${mismatched?'<p class="data-note">These plans use different years or periods. Compare the assumptions before comparing totals; no combined price or difference is calculated.</p>':''}<div class="table-scroll"><table class="college-compare-table"><caption>College costs and financing · amounts in US dollars</caption><thead><tr><th scope="col">Context</th>${ps.map(p=>`<th scope="col">${h(p.institution||'Unnamed college')}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${ps.map(p=>`<td>${h(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function businessPage(state){const b=state.finance.business,labels={appointments:'Paid appointments per working week',collected:'Collected revenue per paid appointment ($)',weeks:'Working weeks per year',share:'Studio share (% of revenue)',rent:'Monthly studio rent ($)',supplies:'Supplies per paid appointment ($)',annualFixed:'Other annual business costs ($)',unpaidHours:'Unpaid design / admin hours per week'};return `${pageHead('SELF-EMPLOYMENT · ILLUSTRATION ONLY','Understand how the business works.','Use your own assumptions. This is not observed income, a typical salary, or an expected outcome.')}<div class="business-layout"><section class="panel"><div class="form-row">${Object.entries(labels).map(([key,label])=>`<div class="field"><label class="label" for="business-${key}">${label}</label><input id="business-${key}" type="number" min="0" step="0.01" data-business="${key}" value="${h(b[key])}" placeholder="No assumption yet"></div>`).join('')}</div><div class="field"><label class="label" for="business-notes">Assumptions / source of these inputs</label><textarea id="business-notes" data-business="notes" maxlength="2000">${h(b.notes)}</textarea></div><p class="field-help">Include cancellations in paid appointments. Check insurance, equipment, training, licensing, and bookkeeping in annual costs. Use studio share and rent together only if both actually apply.</p></section><section class="context-panel business-output" id="business-output" aria-live="polite">${businessOutput(b)}</section></div><section class="data-note"><p>Profit shown is before personal tax, health coverage, retirement saving, and other personal costs. Unpaid hours are recorded separately, not silently priced as paid work. A negative result remains a loss.</p><p>${ext('IRS business-income and self-employment guidance',financeSources.irs)}</p><a href="#/career/tattoo">Back to the tattoo career example ↗</a> · <a href="#/money">College plans ↗</a></section>`;}
export function businessOutput(b){const r=businessScenario(b);return `<span class="overline">YOUR ASSUMPTIONS · ILLUSTRATION</span><h2>Revenue → expenses → profit.</h2><dl class="budget-rows"><div><dt>Annual gross business revenue</dt><dd>${usd(r.revenue)}</dd></div><div><dt>Annual business expenses</dt><dd>${usd(r.expenses)}</dd></div><div><dt>Before-tax operating profit / loss</dt><dd>${usd(r.profit)}</dd></div></dl>${r.issues.map(x=>`<p class="calculation-warning">${h(x)}</p>`).join('')}<p>This does not supply a missing empirical salary. It does not calculate take-home pay or an effective hourly wage.</p>`;}
export function reportFinancialContext(state){const f=state.finance;if(!f?.includeInReport||(!f.plans.length&&!Object.values(f.business).some(v=>String(v).trim())))return '';return `<section class="report-finance"><span class="overline">PERSONAL FINANCIAL CONTEXT · INCLUDED BY YOUR CHOICE</span><h2>Education and money, with assumptions.</h2>${f.plans.map(p=>`<article><h3>${h(p.institution||'Unnamed college')}</h3><p>${h(p.program)} · ${h(p.year)} · ${h(p.residency)} · ${h(p.living)}</p><p>Source: ${h(p.source||'Not recorded')} · checked ${h(p.checkedOn||'Not recorded')}</p>${collegeCalculation(p)}</article>`).join('')}${Object.values(f.business).some(v=>String(v).trim())?`<article class="report-business">${businessOutput(f.business)}<p>Scenario assumptions: ${Object.entries(f.business).filter(([k,v])=>k!=='notes'&&String(v).trim()).map(([k,v])=>`${h(k)}: ${h(v)}`).join(' · ')}</p>${f.business.notes?`<p>${h(f.business.notes)}</p>`:''}<p>${ext('IRS self-employment guidance',financeSources.irs)}</p></article>`:''}<a class="text-link no-print" href="#/money">Review college plans ↗</a></section>`;}
function missingPage(){return pageHead('LET’S FIND YOUR WAY BACK','That career is not in the catalog yet.','Browse the collection or add your own subject to your results.');}
